parameters.jsonBody:
={
  "type": "message",
  "attachments": [{
    "contentType": "application/vnd.microsoft.card.adaptive",
    "content": {
      "type": "AdaptiveCard",
      "version": "1.4",
      "body": [
        {
          "type": "TextBlock",
          "text": "✅ New smenso Task created",
          "weight": "Bolder",
          "size": "Large"
        },
        {
          "type": "TextBlock",
          "text": "{{ $('Prepare Fields').item.json.title }}",
          "wrap": true
        },
        {
          "type": "TextBlock",
          "text": "{{ $('Prepare Fields').item.json.description }}",
          "wrap": true,
          "isSubtle": true
        }
      ]
    }
  }]
}
